defmodule WordDictionary do def init_(), do: Process.put({__MODULE__, :trie}, %{}); def add_word(word) do root = Process.get({__MODULE__, :trie}, %{}); Process.put({__MODULE__, :trie}, insert(String.to_charlist(word), root)) end; def search(word), do: matches(Process.get({__MODULE__, :trie}, %{}), String.to_charlist(word)); defp insert([], node), do: Map.put(node, :terminal, true); defp insert([letter | rest], node), do: Map.put(node, letter, insert(rest, Map.get(node, letter, %{}))); defp matches(node, []), do: Map.get(node, :terminal, false); defp matches(node, [46 | rest]), do: Enum.any?(node, fn {key, child} -> key != :terminal and matches(child, rest) end); defp matches(node, [letter | rest]) do case Map.get(node, letter) do nil -> false; child -> matches(child, rest) end end end
